def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    fill = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Grid lines contain mostly non-background cells.
    rows = [r for r in range(h) if sum(x != fill for x in grid[r]) > w / 2]
    cols = [c for c in range(w) if sum(grid[r][c] != fill for r in range(h)) > h / 2]

    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]

    crossings = {(r, c) for r in rows for c in cols}
    line_colors = [
        grid[r][c]
        for r in rows for c in range(w)
        if (r, c) not in crossings
    ] + [
        grid[r][c]
        for c in cols for r in range(h)
        if (r, c) not in crossings
    ]
    line_color = Counter(line_colors).most_common(1)[0][0] if line_colors else fill

    out = [[fill for _ in range(len(cols) - 1)] for _ in range(len(rows) - 1)]
    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            vals = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            if vals.count(vals[0]) == 4 and vals[0] != line_color:
                out[i][j] = vals[0]

    # Remove empty outer margins.
    active_rows = [i for i, row in enumerate(out) if any(x != fill for x in row)]
    active_cols = [j for j in range(len(out[0])) if any(out[i][j] != fill for i in range(len(out)))]
    if not active_rows or not active_cols:
        return [[fill]]
    return [row[active_cols[0]:active_cols[-1] + 1]
            for row in out[active_rows[0]:active_rows[-1] + 1]]
